import java.text.DecimalFormat;
import java.util.Scanner;
public class JAverageDouble {
	public static void main(String[] args) {
		//Paso 1: Definir las variables que necesitamos para este programa
		double total = 0;
		int count = 0;
		double average;
		///Paso 2: Leer el primer numero que ingresa el usuario
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese un numero: ");
		double num = scan.nextDouble();
		//Paso 3: Procesar el numero que el usuario ha ingresado, luego recibir y procesar los siguientes numeros mientras el usuario ingrese un numero no negativo; de lo contrario detenerse
		while (num >= 0.0) {
			count++;
			total += num;
			System.out.println("La suma hasta ahora es " + total+", contador = "+count);
			System.out.println("Ingrese un numero: ");
			num = scan.nextDouble();
		}
		scan.close();
		//Paso 4: Calcular e imprimir el promedio de los numeros ingresados por el usuario
		if (count == 0) {
			System.out.println("No se ingresaron numeros.");
		} else {
			average = total / count;
			DecimalFormat fmt = new DecimalFormat("0.###");
			System.out.println("El promedio es " + fmt.format(average));
		}
	}
}

